@import "tailwindcss";
@import "@fontsource-variable/geist";
@import "@fontsource-variable/geist-mono";

@theme inline {
  --font-sans: "Geist Variable", ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-mono: "Geist Mono Variable", ui-monospace, "SF Mono", Menlo, monospace;

  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-sunken: var(--sunken);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);

  --color-overlap: var(--overlap);
  --color-overlap-ink: var(--overlap-ink);
  --color-overlap-soft: var(--overlap-soft);
  --color-overlap-text: var(--overlap-text);

  --color-now: var(--now);
  --color-day: var(--day);
  --color-warn-soft: var(--warn-soft);
  --color-warn-line: var(--warn-line);
  --color-warn-text: var(--warn-text);
  --color-danger: var(--danger);
  --color-danger-soft: var(--danger-soft);
}

:root {
  color-scheme: light;

  --canvas: #f4f3ef;
  --surface: #ffffff;
  --sunken: #f3f1ec;
  --line: #e7e4dd;
  --line-strong: #d4d0c6;
  --ink: #16171a;
  --ink-2: #4a4d54;
  --ink-3: #7f828a;

  --overlap: #2fca6b;
  --overlap-ink: #032a12;
  --overlap-soft: #e3f7ea;
  --overlap-text: #127a3c;
  --overlap-seam: rgb(3 42 18 / 0.14);

  --awake: #ffffff;
  --awake-border: #e2ded4;
  --awake-ink: #2a2c31;
  --awake-seam: #ece9e2;

  --asleep: #efede7;
  --asleep-border: #efede7;
  --asleep-ink: #aeaaa0;
  --asleep-hatch: rgb(40 36 20 / 0.045);
  --asleep-seam: rgb(40 36 20 / 0.035);

  --now: #f0641e;
  --day: #5b54d6;

  --warn-soft: #fdf5e6;
  --warn-line: #f1d7a1;
  --warn-text: #874a07;
  --danger: #d92d20;
  --danger-soft: #fdeceb;

  --shadow-card: 0 1px 2px rgb(30 25 10 / 0.04), 0 14px 36px -18px rgb(30 25 10 / 0.14);
  --shadow-pop: 0 2px 6px rgb(30 25 10 / 0.05), 0 24px 48px -16px rgb(30 25 10 / 0.22);
}

@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;

    --canvas: #0b0c0e;
    --surface: #131519;
    --sunken: #0e1013;
    --line: #23262c;
    --line-strong: #32363e;
    --ink: #eef0f2;
    --ink-2: #b3b7be;
    --ink-3: #757a84;

    --overlap: #34d474;
    --overlap-ink: #01240e;
    --overlap-soft: rgb(52 212 116 / 0.11);
    --overlap-text: #62e396;
    --overlap-seam: rgb(1 36 14 / 0.22);

    --awake: #1c1f24;
    --awake-border: #292d34;
    --awake-ink: #e2e4e8;
    --awake-seam: #262a31;

    --asleep: #0f1114;
    --asleep-border: #171a1e;
    --asleep-ink: #4b5058;
    --asleep-hatch: rgb(255 255 255 / 0.028);
    --asleep-seam: rgb(255 255 255 / 0.035);

    --now: #ff7a3d;
    --day: #a3a0ff;

    --warn-soft: rgb(245 165 36 / 0.08);
    --warn-line: rgb(245 165 36 / 0.24);
    --warn-text: #f4c46e;
    --danger: #f87171;
    --danger-soft: rgb(248 113 113 / 0.12);

    --shadow-card: 0 1px 0 rgb(255 255 255 / 0.03) inset, 0 18px 40px -24px rgb(0 0 0 / 0.7);
    --shadow-pop: 0 1px 0 rgb(255 255 255 / 0.04) inset, 0 24px 60px -18px rgb(0 0 0 / 0.8);
  }
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
    -webkit-tap-highlight-color: transparent;
  }

  body {
    background-color: var(--canvas);
    color: var(--ink);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  ::selection {
    background: color-mix(in oklab, var(--overlap) 35%, transparent);
  }

  :focus-visible {
    outline: 2px solid color-mix(in oklab, var(--ink) 75%, transparent);
    outline-offset: 2px;
  }

  button:not(:disabled),
  [role="option"]:not([aria-disabled="true"]) {
    cursor: pointer;
  }
}

@layer components {
  .card {
    background-color: var(--surface);
    border: 1px solid var(--line);
    border-radius: 1.25rem;
    box-shadow: var(--shadow-card);
  }

  .popover {
    background-color: var(--surface);
    border: 1px solid var(--line);
    border-radius: 1rem;
    box-shadow: var(--shadow-pop);
  }

  .kbd {
    display: inline-grid;
    place-items: center;
    min-width: 1.25rem;
    height: 1.25rem;
    padding-inline: 0.3rem;
    border: 1px solid var(--line);
    border-bottom-width: 2px;
    border-radius: 0.375rem;
    background: var(--surface);
    color: var(--ink-3);
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    line-height: 1;
  }

  .bg-glow {
    background:
      radial-gradient(55% 90% at 50% 0%, color-mix(in oklab, var(--overlap) 13%, transparent), transparent 70%),
      radial-gradient(30% 60% at 85% 0%, color-mix(in oklab, var(--now) 7%, transparent), transparent 70%);
  }

  /* ---------- Availability colour tokens (cells, legend swatches) ---------- */

  [data-availability="asleep"] {
    --cell-bg: var(--asleep);
    --cell-border: var(--asleep-border);
    --cell-ink: var(--asleep-ink);
    --cell-seam: var(--asleep-seam);
    --cell-pattern: repeating-linear-gradient(135deg, var(--asleep-hatch) 0 1px, transparent 1px 6px);
  }

  [data-availability="awake"] {
    --cell-bg: var(--awake);
    --cell-border: var(--awake-border);
    --cell-ink: var(--awake-ink);
    --cell-seam: var(--awake-seam);
    --cell-pattern: none;
  }

  [data-availability="overlap"] {
    --cell-bg: var(--overlap);
    --cell-border: var(--overlap);
    --cell-ink: var(--overlap-ink);
    --cell-seam: var(--overlap-seam);
    --cell-pattern: none;
  }

  .swatch {
    display: inline-block;
    width: 0.875rem;
    height: 0.875rem;
    flex-shrink: 0;
    border: 1px solid var(--cell-border);
    border-radius: 0.25rem;
    background-color: var(--cell-bg);
    background-image: var(--cell-pattern);
  }

  /* ---------- Desktop grid geometry ---------- */

  .desktop-grid {
    --label-w: 11.5rem;
    --action-w: 2.75rem;
    --cell-min: 1.875rem;
    --axis-h: 2.25rem;
    --grid-cols: var(--label-w) repeat(24, minmax(var(--cell-min), 1fr)) var(--action-w);
    min-width: calc(var(--label-w) + var(--action-w) + 24 * var(--cell-min));
  }

  @media (min-width: 64rem) {
    .desktop-grid {
      --label-w: 14rem;
      --cell-min: 2rem;
    }
  }

  /* ---------- Hour cell ----------
     Adjacent cells in the same state join into one continuous band. The joined
     side trades its outer padding for inner padding so the label never shifts. */

  .hour-cell {
    --join-pad: 2px;
    display: flex;
    min-width: 0;
  }

  .hour-cell[data-orientation="row"] {
    height: 3rem;
    padding-inline: var(--join-pad);
  }

  .hour-cell[data-orientation="column"] {
    padding-block: var(--join-pad);
    padding-inline: 3px;
  }

  .hour-cell__box {
    display: flex;
    flex: 1;
    min-width: 0;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--cell-border);
    border-radius: 0.5rem;
    background-color: var(--cell-bg);
    background-image: var(--cell-pattern);
    color: var(--cell-ink);
    font-family: var(--font-mono);
    font-variant-numeric: tabular-nums;
    line-height: 1;
    transition:
      background-color 180ms ease,
      border-color 180ms ease,
      color 180ms ease;
  }

  .hour-cell__content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
  }

  .hour-cell[data-orientation="column"] .hour-cell__content {
    flex-direction: row;
    align-items: baseline;
    gap: 0.15rem;
  }

  .hour-cell__time {
    font-size: 0.8125rem;
    font-weight: 500;
    letter-spacing: -0.03em;
    white-space: nowrap;
  }

  .hour-cell__time sup {
    position: relative;
    top: -0.45em;
    margin-left: 0.05em;
    font-size: 0.62em;
    vertical-align: baseline;
  }

  .hour-cell__suffix {
    font-size: 0.5625rem;
    font-weight: 500;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    opacity: 0.72;
  }

  .hour-cell[data-orientation="column"] .hour-cell__suffix:not([data-day]) {
    font-size: 0.6875rem;
    letter-spacing: 0;
    text-transform: none;
  }

  .hour-cell__suffix[data-day] {
    color: var(--day);
    font-weight: 700;
    opacity: 1;
  }

  .hour-cell[data-availability="asleep"] .hour-cell__suffix[data-day] {
    opacity: 0.75;
  }

  .hour-cell[data-availability="overlap"] .hour-cell__time {
    font-weight: 700;
  }

  .hour-cell[data-availability="overlap"] .hour-cell__suffix {
    font-weight: 650;
    opacity: 0.8;
  }

  .hour-cell[data-availability="overlap"] .hour-cell__suffix[data-day] {
    color: inherit;
    opacity: 1;
  }

  .hour-cell[data-orientation="row"][data-join-prev] .hour-cell__box {
    margin-left: calc(-1 * var(--join-pad));
    padding-left: var(--join-pad);
    border-left-color: var(--cell-seam);
    border-top-left-radius: 0;
    border-bottom-left-radius: 0;
  }

  .hour-cell[data-orientation="row"][data-join-next] .hour-cell__box {
    margin-right: calc(-1 * var(--join-pad));
    padding-right: var(--join-pad);
    border-right-color: transparent;
    border-top-right-radius: 0;
    border-bottom-right-radius: 0;
  }

  .hour-cell[data-orientation="column"][data-join-prev] .hour-cell__box {
    margin-top: calc(-1 * var(--join-pad));
    padding-top: var(--join-pad);
    border-top-color: var(--cell-seam);
    border-top-left-radius: 0;
    border-top-right-radius: 0;
  }

  .hour-cell[data-orientation="column"][data-join-next] .hour-cell__box {
    margin-bottom: calc(-1 * var(--join-pad));
    padding-bottom: var(--join-pad);
    border-bottom-color: transparent;
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
  }

  /* ---------- Now indicator ---------- */

  .now-line {
    position: absolute;
    border-radius: 999px;
    background-color: var(--now);
    box-shadow: 0 0 0 1.5px color-mix(in oklab, var(--surface) 85%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

