import { useId } from 'react';

export function LogoMark({ className }: { className?: string }) {
  const clipId = useId();
  return (
    <svg viewBox="0 0 40 40" className={className} aria-hidden>
      <defs>
        <clipPath id={clipId}>
          <circle cx="16" cy="20" r="10" />
        </clipPath>
