            className="popover absolute top-full right-0 z-40 mt-2 w-full origin-top-right sm:w-[23rem]"
          >
            <SettingsPanel onDone={() => setOpen(false)} />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

