import { chromium } from 'playwright-core';

const URL = 'http://localhost:9362/';
const OUT = new URL('./', import.meta.url).pathname;
const errors = [];
const log = (...args) => console.log('•', ...args);

const browser = await chromium.launch({ channel: 'chrome', headless: true });

async function newPage(options = {}) {
  const context = await browser.newContext({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 2, ...options });
  const page = await context.newPage();
  page.on('console', (msg) => msg.type() === 'error' && errors.push(msg.text()));
  page.on('pageerror', (err) => errors.push(err.message));
  return { context, page };
}

const rowNames = (page) =>
  page.$$eval('[role="rowheader"] button span.truncate.text-\\[0\\.9375rem\\]', (els) => els.map((e) => e.textContent));

// ---------- Desktop, defaults ----------
{
  const { context, page } = await newPage();
  await page.goto(URL);
  await page.waitForSelector('[role="table"]');
  log('title:', await page.title());
  log('h1:', await page.textContent('h1'));
  log('rows:', await rowNames(page));
  log('summary:', (await page.textContent('#overlap-summary-title'))?.trim());
  log('badges:', await page.$$eval('section[aria-labelledby="overlap-summary-title"] .rounded-full.border', (els) => els.map((e) => e.textContent)));
  log('hint present:', await page.getByText('Green cells = everyone awake').isVisible());
  log('overlap cells:', await page.locator('.hour-cell[data-availability="overlap"]').count());
  await page.screenshot({ path: `${OUT}01-desktop-default.png`, fullPage: true });

  // hover a column
  const cell = page.locator('[role="row"]').nth(1).locator('.hour-cell').nth(7);
  await cell.hover();
  await page.waitForTimeout(150);
  await page.locator('section[aria-label="Timezone grid"]').screenshot({ path: `${OUT}02-desktop-hover.png` });

  // Base mode
  await page.getByRole('radio', { name: 'Base' }).click();
  await page.waitForTimeout(300);
  log('base summary:', (await page.textContent('#overlap-summary-title'))?.trim());
  log('base lines:', await page.$$eval('section[aria-labelledby="overlap-summary-title"] li', (els) => els.map((e) => e.textContent)));
  await page.screenshot({ path: `${OUT}03-desktop-base.png`, fullPage: true });

  // Promote Denpasar
  await page.getByRole('button', { name: 'Make Denpasar the reference city' }).click();
  await page.waitForTimeout(500);
  log('after promote:', await rowNames(page));

  // Add Mumbai via search + keyboard
  await page.keyboard.press('/');
  await page.keyboard.type('mum');
  await page.waitForTimeout(150);
  await page.screenshot({ path: `${OUT}04-desktop-search.png` });
  await page.keyboard.press('Enter');
  await page.waitForTimeout(400);
  log('after add:', await rowNames(page));

  // Duplicate prevention
  await page.getByRole('combobox').fill('geneva');
  await page.waitForTimeout(150);
  log('geneva option disabled:', await page.locator('[role="option"][aria-disabled="true"]').count());
  await page.keyboard.press('Escape');
  await page.keyboard.press('Escape');

  // Settings
  await page.getByRole('button', { name: /Awake/ }).click();
  await page.waitForTimeout(250);
  await page.screenshot({ path: `${OUT}05-desktop-settings.png` });
  await page.getByLabel('Wake up').selectOption('22');
  await page.getByLabel('Go to sleep').selectOption('6');
  await page.getByRole('radio', { name: '24-hour' }).click();
  await page.waitForTimeout(250);
  await page.screenshot({ path: `${OUT}06-desktop-overnight-24h.png`, fullPage: true });
  await page.keyboard.press('Escape');

  // Persistence
  const before = await page.evaluate(() => localStorage.getItem('timezone-overlap'));
  await page.reload();
  await page.waitForSelector('[role="table"]');
  log('persisted:', before);
  log('after reload rows:', await rowNames(page), 'mode base checked:', await page.getByRole('radio', { name: 'Base' }).getAttribute('aria-checked'));

  // Zero overlap warning in meeting mode
  await page.getByRole('radio', { name: 'Meeting' }).click();
  await page.getByRole('button', { name: /Awake/ }).click();
  await page.getByRole('button', { name: /Workday/ }).click();
  await page.keyboard.press('Escape');
  await page.waitForTimeout(250);
  log('zero overlap:', (await page.textContent('#overlap-summary-title'))?.trim());
  await page.screenshot({ path: `${OUT}07-desktop-no-overlap.png`, fullPage: true });

  // Remove + undo
  await page.getByRole('button', { name: 'Remove Mumbai' }).click();
  await page.waitForTimeout(300);
  log('toast:', await page.locator('[role="status"]').textContent());
  await page.getByRole('button', { name: 'Undo' }).click();
  await page.waitForTimeout(400);
  log('after undo:', await rowNames(page));
  await context.close();
}

// ---------- Fresh context = defaults ----------
{
  const { context, page } = await newPage();
  await page.goto(URL);
  await page.waitForSelector('[role="table"]');
  log('fresh rows:', await rowNames(page));
  await context.close();
}

// ---------- Narrow desktop (horizontal scroll) ----------
{
  const { context, page } = await newPage({ viewport: { width: 820, height: 900 } });
  await page.goto(URL);
  await page.waitForSelector('[role="table"]');
  await page.screenshot({ path: `${OUT}08-tablet.png`, fullPage: true });
  await context.close();
}

// ---------- Dark mode ----------
{
  const { context, page } = await newPage({ colorScheme: 'dark' });
  await page.goto(URL);
  await page.waitForSelector('[role="table"]');
  await page.screenshot({ path: `${OUT}09-desktop-dark.png`, fullPage: true });
  await context.close();
}

// ---------- Mobile ----------
{
  const { context, page } = await newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 3 });
  await page.goto(URL);
  await page.waitForSelector('[role="table"]');
  log('mobile column headers:', await page.locator('[role="columnheader"]').count(), 'desktop rowheaders:', await page.locator('[role="rowheader"]').count());
  await page.screenshot({ path: `${OUT}10-mobile.png`, fullPage: true });
  await page.evaluate(() => window.scrollTo(0, 900));
  await page.waitForTimeout(200);
  await page.screenshot({ path: `${OUT}11-mobile-scrolled.png` });
  await context.close();
}

{
  const { context, page } = await newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 3, colorScheme: 'dark' });
  await page.goto(URL);
  await page.waitForSelector('[role="table"]');
  await page.screenshot({ path: `${OUT}12-mobile-dark.png`, fullPage: true });
  await context.close();
}

log('console errors:', errors.length ? errors : 'none');
await browser.close();

