import { chromium } from 'playwright-core';

const OUT = new URL('./', import.meta.url).pathname;
const browser = await chromium.launch({ channel: 'chrome', headless: true });
const errors = [];

for (const width of [768, 820, 1024, 1280, 1440]) {
  const context = await browser.newContext({ viewport: { width, height: 900 }, deviceScaleFactor: 2 });
  const page = await context.newPage();
  page.on('pageerror', (err) => errors.push(err.message));
  await page.goto('http://localhost:9362/');
  await page.waitForSelector('[role="table"]');
  await page.waitForTimeout(200);
  const metrics = await page.evaluate(() => {
    const scroller = document.querySelector('[role="table"]').parentElement;
    const cell = document.querySelector('.hour-cell[data-orientation="row"] .hour-cell__box');
    const time = document.querySelector('.hour-cell__time');
    return {
      overflowPx: scroller.scrollWidth - scroller.clientWidth,
      cellWidth: Math.round(cell.getBoundingClientRect().width * 10) / 10,
      fade: !!document.querySelector('.bg-linear-to-l'),
      timeFont: getComputedStyle(time).fontSize,
    };
  });
  console.log(width, JSON.stringify(metrics));
  if (width === 1024 || width === 820) await page.screenshot({ path: `${OUT}r-${width}.png`, fullPage: true });
  await context.close();
}

// Fractional offsets in the narrowest non-scrolling desktop layout
{
  const context = await browser.newContext({ viewport: { width: 1024, height: 900 }, deviceScaleFactor: 2 });
  await context.addInitScript(() => {
    localStorage.setItem(
      'timezone-overlap',
      JSON.stringify({
        state: { cityIds: ['san-francisco', 'mumbai', 'kathmandu', 'tehran', 'london'], mode: 'meeting', settings: { wakeHour: 7, sleepHour: 23, timeFormat: '24h' } },
        version: 1,
      }),
    );
