        disabled && 'opacity-45',
      )}
    >
      <span className="grid h-6 w-8 shrink-0 place-items-center rounded-md border border-line bg-surface font-mono text-[0.625rem] font-semibold text-ink-2">
        {city.countryCode}
      </span>
      <span className="min-w-0 flex-1">
